      <tr><td>Tokens</td><td>${formatTokens(ws2.totalTokens)}</td><td>${formatTokens(bs2.totalTokens)}</td><td class="delta">${d.totalTokensDelta !== void 0 ? escapeHtml(formatDelta(d.totalTokensDelta, 0)) : "n/a"}</td></tr>
